-- ═════════════════════════════════════════════════════════════════════════════
-- 농스닥 PostgreSQL 스키마
--
-- 빈 DB 에 한 번 실행하면 테이블 6개가 모두 만들어진다.
--   · docker compose 로 띄우면 처음 한 번 자동 실행된다
--     (/docker-entrypoint-initdb.d 에 이 파일을 넣어 둔다 — docker-compose.yml)
--   · 손으로:  psql -U nongsdak -d nongsdak -f database/schema.sql
--
-- Oracle(v1.0.0, database/oracle/*.sql) 에서 바뀐 점
--   · NUMBER 일련번호 + SEQUENCE  ->  BIGINT GENERATED BY DEFAULT AS IDENTITY
--       (BY DEFAULT 인 이유: Oracle 에서 옮겨 올 때 기존 번호를 그대로 넣기 위해서.
--        옮긴 뒤에는 setval 로 번호를 이어 준다 — 데이터 이전 스크립트가 한다)
--   · VARCHAR2(n CHAR)  ->  VARCHAR(n)       (PostgreSQL 은 원래 글자 수 기준)
--   · NUMBER(12,2)      ->  NUMERIC(12,2)
--   · 조사일 DATE       ->  DATE              (Oracle DATE 는 시각까지 품지만 조사일은 날짜뿐이다)
--   · 시각 DATE + SYSDATE -> TIMESTAMPTZ + now()   (서버가 UTC 여도 시각이 어긋나지 않게)
--   · CLOB 응답 원문    ->  JSONB              (JSON 으로 저장해 안을 조회할 수 있다)
--   · 이름은 대문자로 적지만 따옴표를 안 쳤으므로 PostgreSQL 안에서는 소문자로 저장된다
--     (tbl_daily_price). 쿼리에서 대문자 · 소문자 아무렇게나 써도 같다.
-- ═════════════════════════════════════════════════════════════════════════════


-- ── 시세 ─────────────────────────────────────────────────────────────────────
CREATE TABLE TBL_DAILY_PRICE (
    PRICE_NO        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    SURVEY_DATE     DATE          NOT NULL,
    MARKET_TYPE     VARCHAR(10)   NOT NULL,
    CATEGORY_NAME   VARCHAR(20)   NOT NULL,
    CATEGORY_CODE   VARCHAR(5)    NOT NULL,
    ITEM_CODE       VARCHAR(10)   NOT NULL,
    ITEM_NAME       VARCHAR(40)   NOT NULL,
    KIND_CODE       VARCHAR(10)   NOT NULL,
    KIND_NAME       VARCHAR(60),
    RANK_NAME       VARCHAR(30)   NOT NULL,
    RANK_CODE       VARCHAR(10),
    UNIT            VARCHAR(20),
    PRICE_TODAY     NUMERIC(12, 2),
    PRICE_1D        NUMERIC(12, 2),
    PRICE_1W        NUMERIC(12, 2),
    PRICE_2W        NUMERIC(12, 2),
    PRICE_1M        NUMERIC(12, 2),
    PRICE_1Y        NUMERIC(12, 2),
    PRICE_NORMAL    NUMERIC(12, 2),
    PRICE_1D_DATE   DATE,
    PRICE_1W_DATE   DATE,
    PRICE_2W_DATE   DATE,
    CREATED_AT      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    -- 0원은 '조사 없음' 이다 (2026-11-18 닭 절단육 0원 버그). 수집기가 NULL 로 바꿔 넣지만
    -- 다른 길로 0 이 들어오는 것도 DB 가 막는다.
    CONSTRAINT CK_DAILY_PRICE_POSITIVE CHECK (
        (PRICE_TODAY  IS NULL OR PRICE_TODAY  > 0) AND (PRICE_1D IS NULL OR PRICE_1D > 0) AND
        (PRICE_1W     IS NULL OR PRICE_1W     > 0) AND (PRICE_2W IS NULL OR PRICE_2W > 0) AND
        (PRICE_1M     IS NULL OR PRICE_1M     > 0) AND (PRICE_1Y IS NULL OR PRICE_1Y > 0) AND
        (PRICE_NORMAL IS NULL OR PRICE_NORMAL > 0)
    )
);

-- 자연키. 같은 (시장, 조사일, 품목, 품종, 등급) 은 한 행뿐이다.
-- 수집기의 INSERT ... ON CONFLICT 가 이 제약을 기준으로 '있으면 갱신, 없으면 추가' 한다.
CREATE UNIQUE INDEX UX_DAILY_PRICE_NATURAL
    ON TBL_DAILY_PRICE (MARKET_TYPE, SURVEY_DATE, ITEM_CODE, KIND_CODE, RANK_NAME);
-- 품종 하나의 시계열 (상세 차트)
CREATE INDEX IX_DAILY_ITEM_DATE ON TBL_DAILY_PRICE (MARKET_TYPE, ITEM_CODE, KIND_CODE, SURVEY_DATE);
-- 하루치 전체 (시세판 · 브리핑)
CREATE INDEX IX_DAILY_DATE      ON TBL_DAILY_PRICE (MARKET_TYPE, SURVEY_DATE, CATEGORY_CODE);

COMMENT ON TABLE  TBL_DAILY_PRICE                IS 'KAMIS 일별 시세 (소매 · 도매)';
COMMENT ON COLUMN TBL_DAILY_PRICE.SURVEY_DATE    IS '조사일자';
COMMENT ON COLUMN TBL_DAILY_PRICE.MARKET_TYPE    IS '구분 소매/도매 — 자연키의 일부. 2026-10-15 이전 적재분은 전부 소매';
COMMENT ON COLUMN TBL_DAILY_PRICE.CATEGORY_CODE  IS '부류코드 100 식량작물 / 200 채소류 / 300 특용작물 / 400 과실류 / 500 축산물 / 600 수산물';
COMMENT ON COLUMN TBL_DAILY_PRICE.KIND_CODE      IS '품종코드 — 품목 안에서만 유일. 단독으로 쓰면 안 되고 (ITEM_CODE, KIND_CODE) 복합으로 다룰 것';
COMMENT ON COLUMN TBL_DAILY_PRICE.KIND_NAME      IS '품종명 — 축산물 외에는 끝에 단위가 괄호로 붙어 있음 (예: 흰 콩(국산)(500g))';
COMMENT ON COLUMN TBL_DAILY_PRICE.RANK_NAME      IS '등급 — 상품/중품 외에 부위(삼겹살·목심), 원산지(미국산·호주산), 제품형태(흰우유·절단육)가 섞여 있음. KAMIS 원본의 ''-''(등급없음)는 ''없음''으로 적재';
COMMENT ON COLUMN TBL_DAILY_PRICE.RANK_CODE      IS 'KAMIS 등급코드 (API 의 rank_code). CSV 적재분은 NULL';
COMMENT ON COLUMN TBL_DAILY_PRICE.UNIT           IS '조사 단위 (예: 100g, 1kg, 1마리, 10구)';
COMMENT ON COLUMN TBL_DAILY_PRICE.PRICE_TODAY    IS '당일가격 — 조사가 없거나 KAMIS 가 0 을 주면 NULL';
COMMENT ON COLUMN TBL_DAILY_PRICE.PRICE_NORMAL   IS '평년가격 (KAMIS 다년 평균)';
COMMENT ON COLUMN TBL_DAILY_PRICE.PRICE_1D_DATE  IS 'PRICE_1D 가 실제로 어느 날 값인지 (API 의 day2 "1일전 (MM/DD)"). CSV 적재분은 NULL';
COMMENT ON COLUMN TBL_DAILY_PRICE.PRICE_1W_DATE  IS 'PRICE_1W 의 실제 날짜 (day3). CSV 적재분은 NULL';
COMMENT ON COLUMN TBL_DAILY_PRICE.PRICE_2W_DATE  IS 'PRICE_2W 의 실제 날짜 (day4). CSV 적재분은 NULL';


-- ── 수집 이력 ────────────────────────────────────────────────────────────────
CREATE TABLE TBL_FETCH_LOG (
    LOG_NO          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FETCHED_AT      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    SURVEY_DATE     DATE          NOT NULL,
    MARKET_TYPE     VARCHAR(10),
    CATEGORY_CODE   VARCHAR(5),
    STATUS          VARCHAR(20)   NOT NULL,
    ROWS_FETCHED    INTEGER       NOT NULL DEFAULT 0,
    ROWS_UPSERTED   INTEGER       NOT NULL DEFAULT 0,
    MESSAGE         VARCHAR(500),
    CONSTRAINT CK_FETCH_LOG_STATUS CHECK (STATUS IN ('OK', 'NO_DATA', 'ERROR'))
);

CREATE INDEX IX_FETCH_LOG_TIME ON TBL_FETCH_LOG (FETCHED_AT DESC);
-- 수집 점검(collector/check.py)이 '그날의 시장별 요약행' 을 찾는다
CREATE INDEX IX_FETCH_LOG_DAY  ON TBL_FETCH_LOG (SURVEY_DATE, MARKET_TYPE) WHERE CATEGORY_CODE IS NULL;

COMMENT ON TABLE  TBL_FETCH_LOG                IS 'KAMIS OpenAPI 수집 이력 (실행 1회 = 부류당 1행 + 시장별 요약 1행)';
COMMENT ON COLUMN TBL_FETCH_LOG.FETCHED_AT     IS '수집을 실행한 시각';
COMMENT ON COLUMN TBL_FETCH_LOG.SURVEY_DATE    IS '요청한 조사일자 (실행 시각과 다를 수 있다)';
COMMENT ON COLUMN TBL_FETCH_LOG.MARKET_TYPE    IS '소매 / 도매. 요약행(CATEGORY_CODE NULL)도 시장마다 하나씩 남는다';
COMMENT ON COLUMN TBL_FETCH_LOG.CATEGORY_CODE  IS '부류코드 100~600. 시장별 요약행은 NULL';
COMMENT ON COLUMN TBL_FETCH_LOG.STATUS         IS 'OK=자료 받음 / NO_DATA=주말·공휴일 등 자료 없음(정상) / ERROR=호출 실패. NO_DATA 를 ERROR 로 적으면 매주 경고가 울려 아무도 안 보게 된다';
COMMENT ON COLUMN TBL_FETCH_LOG.ROWS_FETCHED   IS 'API 응답 행 수';
COMMENT ON COLUMN TBL_FETCH_LOG.ROWS_UPSERTED  IS '반영한 행 수 (신규+갱신)';
COMMENT ON COLUMN TBL_FETCH_LOG.MESSAGE        IS '오류 메시지나 비고. 401/403 같은 인증 문제는 여기 남겨 두면 원인 찾기가 빠르다';


-- ── API 응답 원문 ────────────────────────────────────────────────────────────
CREATE TABLE TBL_API_RAW (
    RAW_NO          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FETCHED_AT      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    SURVEY_DATE     DATE          NOT NULL,
    MARKET_TYPE     VARCHAR(10)   NOT NULL,
    CATEGORY_CODE   VARCHAR(5)    NOT NULL,
    ERROR_CODE      VARCHAR(10),
    ITEM_COUNT      INTEGER       NOT NULL DEFAULT 0,
    BODY_HASH       VARCHAR(64)   NOT NULL,
    BODY            JSONB         NOT NULL
);

-- '같은 키의 가장 최근 원문' 을 찾는다 (같으면 다시 넣지 않는다)
CREATE INDEX IX_API_RAW_KEY ON TBL_API_RAW (SURVEY_DATE, MARKET_TYPE, CATEGORY_CODE, RAW_NO);

COMMENT ON TABLE  TBL_API_RAW               IS 'KAMIS OpenAPI 응답 원문. 호출 1회 = 1행. 직전 원문과 같으면 쌓지 않는다';
COMMENT ON COLUMN TBL_API_RAW.SURVEY_DATE   IS '요청한 조사일자 (p_regday)';
COMMENT ON COLUMN TBL_API_RAW.MARKET_TYPE   IS '소매 / 도매';
COMMENT ON COLUMN TBL_API_RAW.BODY_HASH     IS '원문 JSON 텍스트(키 정렬)의 SHA-256. 같은 키의 최신 행과 같으면 새로 넣지 않는다 — 매일 7일치를 다시 받으므로 그대로 쌓으면 같은 응답이 7벌씩 생긴다';
COMMENT ON COLUMN TBL_API_RAW.BODY          IS '응답 JSON. KAMIS 가 condition 에 요청 파라미터를 되돌려주므로 p_cert_key·p_cert_id 는 *** 로 가려 저장한다';


-- ── 회원 · 로그인 세션 ───────────────────────────────────────────────────────
CREATE TABLE TBL_USER (
    USER_NO         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOGIN_ID        VARCHAR(20)   NOT NULL,
    PASSWORD_HASH   VARCHAR(300)  NOT NULL,
    NICKNAME        VARCHAR(20)   NOT NULL,
    CREATED_AT      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    LAST_LOGIN_AT   TIMESTAMPTZ,
    CONSTRAINT UX_USER_LOGIN_ID UNIQUE (LOGIN_ID)
);

COMMENT ON TABLE  TBL_USER                  IS '회원. 시세 조회에는 필요 없고, 장바구니처럼 개인 데이터를 저장할 때만 쓴다';
COMMENT ON COLUMN TBL_USER.LOGIN_ID         IS '로그인 아이디. 영문 소문자·숫자·_ 4~20자. 대소문자를 가리지 않도록 소문자로 저장한다';
COMMENT ON COLUMN TBL_USER.PASSWORD_HASH    IS 'scrypt$n$r$p$salt$hash 형식. 원문 비밀번호는 어디에도 남기지 않는다';
COMMENT ON COLUMN TBL_USER.NICKNAME         IS '화면 표시용 이름 (중복 허용)';

CREATE TABLE TBL_USER_SESSION (
    TOKEN_HASH      VARCHAR(64)   PRIMARY KEY,
    USER_NO         BIGINT        NOT NULL REFERENCES TBL_USER (USER_NO) ON DELETE CASCADE,
    CREATED_AT      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    EXPIRES_AT      TIMESTAMPTZ   NOT NULL
);

CREATE INDEX IX_USER_SESSION_USER ON TBL_USER_SESSION (USER_NO);

COMMENT ON TABLE  TBL_USER_SESSION            IS '로그인 세션. 로그아웃하면 행을 지워 즉시 무효화한다';
COMMENT ON COLUMN TBL_USER_SESSION.TOKEN_HASH IS '쿠키에 담긴 토큰의 SHA-256. 토큰 원문은 저장하지 않는다';
COMMENT ON COLUMN TBL_USER_SESSION.EXPIRES_AT IS '만료 시각. 지난 행은 로그인할 때 함께 정리한다';


-- ── 장바구니 ─────────────────────────────────────────────────────────────────
CREATE TABLE TBL_CART_ITEM (
    CART_NO         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    USER_NO         BIGINT        NOT NULL REFERENCES TBL_USER (USER_NO) ON DELETE CASCADE,
    ITEM_CODE       VARCHAR(10)   NOT NULL,
    KIND_CODE       VARCHAR(10)   NOT NULL,
    RANK_NAME       VARCHAR(30)   NOT NULL,
    QTY             SMALLINT      NOT NULL DEFAULT 1,
    ADDED_AT        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT UX_CART_ITEM     UNIQUE (USER_NO, ITEM_CODE, KIND_CODE, RANK_NAME),
    CONSTRAINT CK_CART_ITEM_QTY CHECK (QTY BETWEEN 1 AND 99)
);

COMMENT ON TABLE  TBL_CART_ITEM            IS '장바구니. 가격은 두지 않고 열 때마다 최신 소매가로 계산한다';
COMMENT ON COLUMN TBL_CART_ITEM.USER_NO    IS 'TBL_USER.USER_NO. 탈퇴하면 같이 지워진다';
COMMENT ON COLUMN TBL_CART_ITEM.RANK_NAME  IS '담을 때 화면에 보인 등급. 바꾸면 다른 가격이 된다';
COMMENT ON COLUMN TBL_CART_ITEM.QTY        IS '수량 1~99. 조사 단위(1포기 · 1kg · 10개) 개수';
